steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        projects(name: \"Mobile Redesign\") {
          nodes {
            id
            name
            description
            issues(first: 50) {
              nodes {
                id
                identifier
                title
                description
                updatedAt
                lastEditedAt
                user {
                  id
                  name
                }
                createdAt
              }
            }
          }
        }
      }
    '
  }'
